import React from 'react';
import { useHistory } from 'react-router-dom';
import styled from 'styled-components';


const DashboardPage = ({ lorryDetails }) => {
  const history = useHistory(); // For navigation

  // Function to handle navigation
  const handleNavigation = (section) => {
    if (section === 'employee') {
      history.push(`/employee/${lorryDetails.id}`);
    } else if (section === 'fuel') {
      history.push(`/fuel/${lorryDetails.id}`);
    } else if (section === 'point') {
      history.push(`/point/${lorryDetails.id}`);
    }
  };

  return (
    <Container>
      {lorryDetails && (
        <>
          <Header>
            <HeaderLeft>Reg. No: {lorryDetails.registration_number}</HeaderLeft>
            <HeaderCenter>{lorryDetails.owner_name}</HeaderCenter>
            <HeaderRight>Phone: {lorryDetails.owner_phone}</HeaderRight>
          </Header>

          <DashboardOptions>
            <OptionButton onClick={() => handleNavigation('employee')}>Employee</OptionButton>
            <OptionButton onClick={() => handleNavigation('fuel')}>Fuel Details</OptionButton>
            <OptionButton onClick={() => handleNavigation('point')}>Point Details</OptionButton>
          </DashboardOptions>
        </>
      )}
    </Container>
  );
};

export default DashboardPage;
